// ===========================================================================
// SWAPPABLE NODE. This is the ONLY place the Apify actor input is defined.
// Mirrors apify/website-content-crawler-input.json. To change the actor input,
// edit the object inside buildApifyInput() and nothing else in this workflow.
// startUrls is the only field built at runtime.
// ===========================================================================
function buildApifyInput(pageUrls) {
  return {
    startUrls: pageUrls.map(function (u) { return { url: u }; }),
    crawlerType: 'playwright:adaptive',
    maxCrawlDepth: 0,
    maxCrawlPages: 3,
    maxResults: 3,
    htmlTransformer: 'none',
    removeElementsCssSelector: 'nav, footer, script, style, noscript',
    saveMarkdown: true,
    saveHtmlAsFile: false,
    saveScreenshots: false,
    summarize: false,
    proxyConfiguration: { useApifyProxy: true }
  };
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const c = items[i].json || {};
  const business = c.businesses || {};

  let pageUrls = Array.isArray(c.page_urls) ? c.page_urls : [];
  pageUrls = pageUrls
    .map(function (u) { return String(u === null || u === undefined ? '' : u).trim(); })
    .filter(function (u) { return u.length > 0; })
    .slice(0, 3);
  // competitors.page_urls has a 1..3 cardinality CHECK, so it should never be
  // empty, but fall back to the main url rather than crawling nothing.
  if (pageUrls.length === 0 && c.url) pageUrls = [String(c.url)];

  out.push({
    json: {
      competitor_id: c.id,
      business_id: c.business_id,
      competitor_name: c.name || '',
      competitor_url: c.url || '',
      page_urls: pageUrls,
      business_name: business.name || '',
      business_city: business.city || '',
      business_offerings: business.offerings || '',
      apify_input: buildApifyInput(pageUrls)
    },
    pairedItem: { item: i }
  });
}
return out;

// Resolve the matching item from an upstream node. itemMatching() follows n8n's
// paired-item chain, which is correct even when a branch filtered items out; the
// index fallback keeps the demo alive if the chain is ever broken.
function ctx(nodeName, i) {
  const n = $(nodeName);
  try {
    const m = n.itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}
  const all = n.all();
  return ((all[i] || all[0]) || { json: {} }).json;
}

// Deterministic hash implemented inline on purpose: the Code node sandbox can
// block require('crypto'), so this workflow depends on no modules at all.
// Two independent 32-bit mixers concatenated into 16 hex chars.
function contentHash(str) {
  const s = String(str);
  let h1 = 0x811c9dc5;
  let h2 = 0x1b873593;
  for (let i = 0; i < s.length; i++) {
    const c = s.charCodeAt(i);
    h1 = (h1 ^ c) >>> 0;
    h1 = Math.imul(h1, 0x01000193) >>> 0;
    h2 = (h2 + c) >>> 0;
    h2 = Math.imul(h2, 0x85ebca6b) >>> 0;
    h2 = (h2 ^ (h2 >>> 13)) >>> 0;
  }
  const a = ('00000000' + (h1 >>> 0).toString(16)).slice(-8);
  const b = ('00000000' + (h2 >>> 0).toString(16)).slice(-8);
  return a + b;
}

function extractPrices(text) {
  const found = String(text).match(/(?:US\$|USD\s?|\$)\s?\d{1,4}(?:,\d{3})*(?:\.\d{1,2})?/g) || [];
  const seen = [];
  for (let i = 0; i < found.length; i++) {
    const p = found[i].replace(/\s+/g, '');
    if (seen.indexOf(p) === -1) seen.push(p);
    if (seen.length >= 80) break;
  }
  return seen;
}

function extractItems(text) {
  const lines = String(text).split('\n');
  const found = [];
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/^[\s>*#|-]+/, '').trim();
    if (line.length < 3 || line.length > 200) continue;
    if (!/\$\s?\d/.test(line)) continue;
    if (found.indexOf(line) === -1) found.push(line);
    if (found.length >= 60) break;
  }
  return found;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const c = ctx('Build Apify Actor Input', i);
  const raw = items[i].json || {};

  // The node runs with "Include Response Headers and Status" on, so the actor's
  // dataset array arrives under .body instead of being split across items.
  let dataset = raw.body !== undefined ? raw.body : raw;
  if (!Array.isArray(dataset)) {
    if (dataset && Array.isArray(dataset.items)) dataset = dataset.items;
    else if (dataset && typeof dataset === 'object') dataset = [dataset];
    else dataset = [];
  }

  let pages = dataset
    .map(function (p) {
      p = p || {};
      const md = p.markdown || p.text || p.content || '';
      return {
        url: String(p.url || p.loadedUrl || p.requestUrl || ''),
        markdown: String(md).replace(/\r\n/g, '\n').replace(/[ \t]+\n/g, '\n').trim()
      };
    })
    .filter(function (p) { return p.url !== '' || p.markdown !== ''; });

  // Sort by URL so the hash never depends on the order Apify happened to finish in.
  pages.sort(function (a, b) { return a.url < b.url ? -1 : (a.url > b.url ? 1 : 0); });
  pages = pages.map(function (p) {
    return { url: p.url, markdown: p.markdown, hash: contentHash(p.url + '\n' + p.markdown) };
  });

  const combined = pages
    .map(function (p) { return '### ' + p.url + '\n\n' + p.markdown; })
    .join('\n\n---\n\n');

  out.push({
    json: {
      competitor_id: c.competitor_id,
      business_id: c.business_id,
      competitor_name: c.competitor_name,
      competitor_url: c.competitor_url,
      business_name: c.business_name,
      business_city: c.business_city,
      business_offerings: c.business_offerings,
      page_count: pages.length,
      pages: pages,
      current_content: combined,
      content_hash: contentHash(combined),
      structured: {
        prices: extractPrices(combined),
        items: extractItems(combined),
        hours: null
      }
    },
    pairedItem: { item: i }
  });
}
return out;

