// ===========================================================================
// The guardrail between a hallucinating model and a 400 from Postgres.
// Every value below is copied character for character from supabase/schema.sql.
// ===========================================================================
const ALLOWED_SIGNAL_TYPE = ['baseline', 'change'];
const ALLOWED_CATEGORY = ['pricing', 'promotion', 'menu_product', 'hours', 'reputation', 'positioning'];
const ALLOWED_IMPACT = ['high', 'medium', 'low'];
const REQUIRED_TEXT = ['title', 'finding', 'why_it_matters', 'recommended_action', 'evidence'];
const IMPACT_ORDER = { high: 0, medium: 1, low: 2 };
const MAX_SIGNALS = 3;

function parseLoose(text) {
  if (text === null || text === undefined) return null;
  let t = String(text).trim();
  t = t.replace(/^```[a-zA-Z]*\s*/, '').replace(/```\s*$/, '').trim();
  try { return JSON.parse(t); } catch (e) {}
  const candidates = [t.indexOf('{'), t.indexOf('[')].filter(function (x) { return x >= 0; });
  if (candidates.length === 0) return null;
  const start = Math.min.apply(null, candidates);
  const end = t.lastIndexOf(t.charAt(start) === '{' ? '}' : ']');
  if (end <= start) return null;
  try { return JSON.parse(t.slice(start, end + 1)); } catch (e) {}
  return null;
}

function toArray(parsed) {
  if (Array.isArray(parsed)) return parsed;
  if (parsed && typeof parsed === 'object') {
    const keys = ['signals', 'data', 'results', 'items', 'output'];
    for (let i = 0; i < keys.length; i++) {
      if (Array.isArray(parsed[keys[i]])) return parsed[keys[i]];
    }
    if (parsed.title || parsed.finding) return [parsed];
  }
  return [];
}

function clean(v) {
  if (v === null || v === undefined) return '';
  return (typeof v === 'string' ? v : String(v)).trim();
}

function enumOf(v) {
  return clean(v).toLowerCase().replace(/[\s-]+/g, '_');
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const d = ctx('Classify Scan Branch', i);
  const expectedType = d.branch === 'baseline' ? 'baseline' : 'change';

  const resp = items[i].json || {};
  let content = '';
  try { content = resp.choices[0].message.content; } catch (e) { content = ''; }

  const raw = toArray(parseLoose(content));
  const kept = [];
  const dropped = [];

  for (let k = 0; k < raw.length; k++) {
    const s = raw[k] || {};
    const declaredType = enumOf(s.signal_type);
    const category = enumOf(s.category);
    const impact = enumOf(s.impact);

    if (declaredType !== '' && ALLOWED_SIGNAL_TYPE.indexOf(declaredType) === -1) {
      dropped.push('signal_type not in enum: ' + declaredType);
      continue;
    }
    if (ALLOWED_CATEGORY.indexOf(category) === -1) {
      dropped.push('category not in enum: ' + category);
      continue;
    }
    if (ALLOWED_IMPACT.indexOf(impact) === -1) {
      dropped.push('impact not in enum: ' + impact);
      continue;
    }

    const text = {};
    let missing = '';
    for (let f = 0; f < REQUIRED_TEXT.length; f++) {
      const field = REQUIRED_TEXT[f];
      const val = clean(s[field]);
      if (val === '') { missing = field; break; }
      text[field] = val;
    }
    if (missing !== '') {
      dropped.push('empty required field: ' + missing);
      continue;
    }

    kept.push({
      // The branch decides signal_type, never the model.
      signal_type: expectedType,
      category: category,
      impact: impact,
      title: text.title.slice(0, 300),
      finding: text.finding,
      why_it_matters: text.why_it_matters,
      recommended_action: text.recommended_action,
      evidence: text.evidence.slice(0, 2000)
    });
  }

  kept.sort(function (a, b) { return IMPACT_ORDER[a.impact] - IMPACT_ORDER[b.impact]; });
  const signals = kept.slice(0, MAX_SIGNALS);

  out.push({
    json: {
      competitor_id: d.competitor_id,
      business_id: d.business_id,
      branch: d.branch,
      content_hash: d.content_hash,
      pages: d.pages,
      structured: d.structured,
      signal_count: signals.length,
      signals: signals,
      dropped_count: dropped.length,
      dropped_reasons: dropped.slice(0, 10)
    },
    pairedItem: { item: i }
  });
}
return out;

// Resolve the matching item from an upstream node. itemMatching() follows n8n's
// paired-item chain, which is correct even when a branch filtered items out; the
// index fallback keeps the demo alive if the chain is ever broken.
function ctx(nodeName, i) {
  const n = $(nodeName);
  try {
    const m = n.itemMatching(i);
    if (m && m.json) return m.json;
  } catch (e) {}
  const all = n.all();
  return ((all[i] || all[0]) || { json: {} }).json;
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const snapshot = items[i].json || {};
  const v = ctx('Validate Signals', i);
  const snapshotId = snapshot.id || null;

  const rows = (Array.isArray(v.signals) ? v.signals : []).map(function (s) {
    return {
      business_id: v.business_id,
      competitor_id: v.competitor_id,
      snapshot_id: snapshotId,
      signal_type: s.signal_type,
      category: s.category,
      impact: s.impact,
      title: s.title,
      finding: s.finding,
      why_it_matters: s.why_it_matters,
      recommended_action: s.recommended_action,
      evidence: s.evidence
    };
  });

  out.push({
    json: {
      competitor_id: v.competitor_id,
      business_id: v.business_id,
      snapshot_id: snapshotId,
      signal_count: rows.length,
      signal_rows: rows
    },
    pairedItem: { item: i }
  });
}
return out;

// Every terminating path converges here: unchanged early-exit, signals inserted,
// and no-signals. Collapses to one item per competitor so the final PATCH runs once.
const seen = {};
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const j = items[i].json || {};
  const id = j.competitor_id || j.id;
  if (!id || seen[id]) continue;
  seen[id] = true;
  out.push({
    json: {
      competitor_id: id,
      branch: j.branch || null,
      signal_count: j.signal_count === undefined ? null : j.signal_count
    },
    pairedItem: { item: i }
  });
}
return out;
